 can(action){const roles={admin:['manage','period','draft','review','approve','post','reverse','reconcile','export'],accountant:['period','draft','review','approve','post','reverse','reconcile','export'],assistant:['draft','reconcile','export'],auditor:['export'],manager:['approve','export']};return (roles[this.company.role]||[]).includes(action);},message(e){return (e.response&&e.response.data&&e.response.data.error)||e.message||'No se pudo completar la operación.';},async get(action,p={}){const companyId=this.companyId;const data=(await this.axios.get('/api/accounting.php',{params:{action,companyId,...p}})).data;if(action!=='context'&&companyId!==this.companyId)throw Error('La empresa seleccionada cambió. Se omitió una respuesta anterior.');return data;},async post(action,p={}){return (await this.axios.post('/api/accounting.php',{...p,action,companyId:this.companyId},{headers:{'X-Accounting-CSRF':this.context.csrf}})).data;},
 async switchCompany(){this.error='';this.dashboard=null;this.filters.branchId=null;this.bankId=null;this.reconciliation=null;try{if(!this.companyId)return;const id=this.companyId;const [company,accounts,branches,banks]=await Promise.all([this.get('company'),this.get('accounts'),this.get('branches'),this.get('banks')]);if(id!==this.companyId)return;this.company=company;this.settings=JSON.parse(JSON.stringify(company.settings));this.accounts=accounts;this.branches=branches;this.banks=banks;await this.load();}catch(e){this.error=this.message(e);}},
 async load(){if(!this.companyId)return;this.error='';try{if(this.tab==='dashboard')this.dashboard=await this.get('dashboard',this.filters);if(this.tab==='accounts')this.accounts=await this.get('accounts');if(this.tab==='entries')this.entries=await this.get('entries',{...this.filters,status:this.entryStatus});if(this.tab==='sources')this.sources=await this.get('sources',this.filters);if(this.tab==='reports'){this.reportPage=1;const data=await this.get('report',{...this.filters,report:this.report,account:this.reportAccount});if(this.report==='statements')this.statement=data;else this.reportRows=data;}if(this.tab==='tax'){this.tax=await this.get('report',{...this.filters,report:'tax'});await this.loadTaxReconciliation();}if(this.tab==='banks')await this.loadBank();if(this.tab==='assets')this.assets=await this.get('assets');if(this.tab==='audit')this.audit=await this.get('audit');if(this.tab==='config'){[this.periods,this.members,this.branches]=await Promise.all([this.get('periods'),this.get('members'),this.get('branches')]);}}catch(e){this.error=this.message(e);}},
 async write(action,p){if(this.busy)return;this.busy=true;this.error='';try{const r=await this.post(action,p);this.success=r.duplicate?'La operación ya existía; se conservó el asiento original.':'Operación guardada.';if(action==='configure'){this.company=await this.get('company');}if(['officialCatalog','starterCatalog','importAccounts','account'].includes(action))this.accounts=await this.get('accounts');const matchId=this.matching?this.matching.Id:null;await this.load();if(action==='match'&&this.reconciliation){this.matching=this.reconciliation.items.find(i=>i.Id===matchId&&Number(i.RemainingAmount)!==0)||null;}return r;}catch(e){this.error=this.message(e);if(this.modal)this.formError=this.error;return null;}finally{this.busy=false;}},
 async importCatalog(action){const r=await this.$swal({title:'Importar catálogo contable',text:'Se validan cuentas y jerarquía antes de guardar. Las clasificaciones con movimientos contabilizados no se sobrescriben.',showCancelButton:true});if(r.isConfirmed)await this.write(action,{});},
 newDraft(){this.draft=accountingDraft();this.draft.electronic={issuerType:'6',issuerDoc:this.company.Ruc,docType:'00',series:'',number:'',reference:''};this.formError='';this.modal='draft';},editAccount(a){this.account=a?{code:a.Code,name:a.Name,parent:a.ParentCode,nature:a.Nature,class:a.Class,group:a.ReportGroup,postable:!!Number(a.Postable),active:!!Number(a.Active)}:{code:'',name:'',parent:'',nature:'debit',class:'asset',group:'asset',postable:true,active:true};this.formError='';this.modal='account';},
 async openEntry(id){try{this.selected=await this.get('entry',{id});this.entryOpen=true;}catch(e){this.error=this.message(e);}},editDraft(){const e=this.selected;this.draft={id:e.Id,version:e.Version,date:e.EntryDate,currency:e.Currency,rate:e.ExchangeRate,memo:e.Memo,document:e.Document,branchId:e.BranchId,electronic:e.ElectronicData?JSON.parse(e.ElectronicData):{issuerType:'6',issuerDoc:this.company.Ruc,docType:'00',series:'',number:'',reference:''},lines:e.lines.map(l=>({account:l.Account,debit:(Number(l.OriginalDebit)/100).toFixed(2),credit:(Number(l.OriginalCredit)/100).toFixed(2),partyType:l.PartyType,partyId:l.PartyId,cashFlow:l.CashFlow}))};this.entryOpen=false;this.modal='draft';},
 async entryAction(transition){try{await this.write('transition',{id:this.selected.Id,version:this.selected.Version,transition});this.selected=await this.get('entry',{id:this.selected.Id});}catch(e){}},async voidTax(){const r=await this.$swal({title:'Anulación tributaria',text:'Requiere reverso contabilizado y constancia/documento de anulación. No sustituye una nota de crédito.',input:'text',showCancelButton:true});if(r.isConfirmed&&r.value){const saved=await this.write('voidTax',{id:this.selected.Id,evidence:r.value});if(saved)await this.openEntry(this.selected.Id);}},async reverseEntry(){const r=await this.$swal({title:'Crear reverso auditable',text:'Motivo de la corrección',input:'text',showCancelButton:true});if(!r.isConfirmed||!r.value)return;try{const result=await this.write('reverse',{id:this.selected.Id,version:this.selected.Version,reason:r.value,date:accountingToday()});await this.openEntry(result.id);}catch(e){}},
