 async periodAction(p){const reopen=p.State==='closed';const r=await this.$swal({title:reopen?'Reabrir período':'Cerrar período',text:reopen?'Indica el motivo':'Se bloqueará la contabilización y modificación de este período.',input:reopen?'text':undefined,showCancelButton:true});if(r.isConfirmed)try{await this.write('closePeriod',{period:p.Period,reopen,reason:r.value||''});}catch(e){}},
 async submitForm(){this.formError='';try{let action=this.modal,p;const data={company:this.companyForm,account:this.account,draft:this.draft,template:this.operation,bank:this.bank,asset:this.asset,source:this.sourceReview};p=JSON.parse(JSON.stringify(data[this.modal]));if(this.modal==='company')action='createCompany';if(this.modal==='draft'&&!this.draft.electronic.number)delete p.electronic;if(this.modal==='draft'&&this.draft.id)action='updateDraft';else if(this.modal==='draft'&&this.draft.opening)action='opening';if(this.modal==='source')action=this.sourceReview.kind==='cash'?'prepareCash':'prepareSource';const r=await this.write(action,p);if(r){this.modal='';if(action==='createCompany'){this.context=await this.get('context');this.companyId=Number(r.id);await this.switchCompany();}if(['bank','account'].includes(action))await this.switchCompany();}}catch(e){this.formError=this.message(e);}},
 async reviewSource(item){try{if(!item.Snapshot)item=await this.get('source',{kind:item.Kind,sourceId:item.SourceId});const snapshot=JSON.parse(item.Snapshot);let sum=0;(snapshot.lines||[]).forEach(l=>sum+=Math.round(Number(l.total)*100));this.sourceReview={kind:item.Kind,sourceId:item.SourceId,hash:item.SourceHash,snapshot,currency:snapshot.currency==='USD'?'USD':'PEN',operation:'',partyId:'',rate:snapshot.rate||'1',purchaseClass:'',returnsInventory:false,reviewed:false,tax:{kind:item.Kind,issueDate:snapshot.date,period:snapshot.date.slice(0,7),docType:snapshot.docType,series:String(snapshot.series),number:String(snapshot.number),partyDocType:(!snapshot.partyDoc||snapshot.partyDoc==='00000000')?'0':(snapshot.partyDoc||'').length===11?'6':((snapshot.partyDoc||'').length===8?'1':'0'),partyDoc:snapshot.partyDoc||'',partyName:snapshot.partyName||'',taxable:'0',exempt:'0',unaffected:'0',freeAmount:'0',freeIgv:'0',igv:'0',otherTaxes:'0',total:(sum/100).toFixed(2),withholding:'0',perception:'0',detraction:'0',creditEligible:false,referenceDoc:snapshot.referenceDoc||'',pleReference:''}};this.formError='';this.modal='source';}catch(e){this.error=this.message(e);}},
 async linkManualSource(item){const id=await this.$swal({title:'Vincular asiento manual revisado',text:'ID del asiento contabilizado que referencia exactamente el documento de origen.',input:'number',showCancelButton:true});if(!id.isConfirmed||!id.value)return;const reason=await this.$swal({title:'Sustento de la vinculación',input:'text',showCancelButton:true});if(reason.isConfirmed&&reason.value)await this.write('resolveSource',{kind:item.Kind,sourceId:item.SourceId,hash:item.SourceHash,manualEntryId:Number(id.value),reason:reason.value});},
 async resolveSource(item){const r=await this.$swal({title:'Resolver conflicto de origen',input:'text',inputPlaceholder:'Motivo y comprobación del reverso o descarte',showCancelButton:true});if(r.isConfirmed&&r.value)await this.write('resolveSource',{kind:item.Kind,sourceId:item.SourceId,hash:item.SourceHash,reason:r.value});},
 async saveStatement(){await this.write('statement',{...this.filters,bankId:this.bankId,...this.statementInput,version:this.reconciliation.statement?this.reconciliation.statement.Version:0});},
 async loadBank(){if(!this.bankId)return;this.reconciliation=await this.get('reconciliation',{...this.filters,bankId:this.bankId});const data=this.reconciliation.statement;this.statementInput=data?{opening:(Number(data.Opening)/100).toFixed(2),closing:(Number(data.Closing)/100).toFixed(2),reference:data.Reference}:{opening:'',closing:'',reference:''};},async unmatch(item){const r=await this.$swal({title:'Deshacer conciliación',input:'text',inputPlaceholder:'Motivo',showCancelButton:true});if(r.isConfirmed&&r.value)try{await this.write('match',{bankItemId:item.Id,unmatch:true,reason:r.value});}catch(e){}},async loadTaxReconciliation(){this.taxMatches=await this.get('taxReconciliation',{period:this.period});},
 async upload(event,kind){const file=event.target.files[0];event.target.value='';if(!file)return;try{if(file.size>5*1024*1024)throw Error('Archivo demasiado grande: máximo 5 MB.');const rows=accountingCSV(await file.text());if(kind==='accounts'){rows.forEach(r=>{r.postable=['1','true'].includes(r.postable);r.active=!['0','false'].includes(r.active);});await this.write('importAccounts',{rows});}if(kind==='bank'){if(!this.bankId)throw Error('Selecciona una cuenta bancaria.');await this.write('importBank',{bankId:this.bankId,rows});}if(kind==='tax'){await this.write('importExternalRegister',{period:this.period,kind:this.taxKind,rows});await this.loadTaxReconciliation();}}catch(e){this.error=this.message(e);}},
 async exportReport(format){try{const response=await this.axios.get('/api/accounting.php',{params:{action:'export',companyId:this.companyId,...this.filters,report:this.report,account:this.reportAccount,format,period:this.period},responseType:'blob'});const url=URL.createObjectURL(response.data),a=document.createElement('a');a.href=url;const disposition=response.headers['content-disposition']||'';a.download=(disposition.match(/filename="([^"]+)"/)||[])[1]||'contabilidad.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}catch(e){if(e.response&&e.response.data instanceof Blob){try{this.error=JSON.parse(await e.response.data.text()).error;return;}catch(ignore){}}this.error=this.message(e);}}
 }
};
</script>
