footer{display:flex;justify-content:flex-end;gap:10px;border-top:1px solid #ddd;padding-top:16px;margin-top:16px}.co-grid label{display:block;font-size:12px}.co-grid .form-control,.co-grid .custom-select{margin-bottom:8px}.co-upload{display:inline-flex;position:relative;overflow:hidden;border:1px solid #bfd3df;padding:7px 12px;border-radius:6px;background:#eef5f9;cursor:pointer;font-size:13px;margin:0}.co-upload input{position:absolute;inset:0;opacity:0;cursor:pointer}.co-empty{text-align:center;padding:60px;color:#58758b}.co-inline{display:flex;gap:8px}.co-links{display:flex;gap:20px;margin:15px 0}.co-app >>> .table{font-size:12px}.co-app >>> .table th{background:#edf4f8;color:#2b5066;white-space:nowrap}.co-app >>> .btn{font-size:13px}.co-app >>> .form-control,.co-app >>> .custom-select{font-size:13px;min-height:34px;height:36px}.co-app >>> .table td{vertical-align:middle}.co-app >>> .table input{min-width:85px}.co-app >>> .alert{margin:10px 0}
@media(max-width:900px){.co-app{padding:10px}.co-header h1{font-size:18px;line-height:24px}.co-filters{flex-wrap:wrap}.co-filters label{min-width:140px}.co-grid{grid-template-columns:1fr}.co-form-grid{grid-template-columns:1fr 1fr}.co-kpis{grid-template-columns:repeat(2,1fr)}}@media(max-width:500px){.co-header{padding:8px 12px;flex-wrap:wrap}.co-header>.btn{margin:0}.co-form-grid{grid-template-columns:1fr}.co-kpis strong{font-size:19px}.co-kpis article{padding:12px}.co-links{flex-direction:column;gap:8px}}
